param(
    [switch]$Commit,
    [switch]$AllowOtherBranch
)

$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest

$ExpectedBranch = 'agent/lobby-mvp-integration'
$InstallerVersion = 1
$PayloadSha256 = '21828b60fe233a38382910c79525e4971d1da8c32f8221856cceb87b62aae444'

function Fail([string]$Message) {
    Write-Host ''
    Write-Host ('ERRO: ' + $Message) -ForegroundColor Red
    exit 1
}

function Run-Git {
    param(
        [Parameter(Mandatory=$true)][string[]]$Args,
        [string]$WorkingDirectory
    )

    $old = Get-Location
    try {
        if ($WorkingDirectory) {
            Set-Location $WorkingDirectory
        }
        & git @Args
        if ($LASTEXITCODE -ne 0) {
            throw "git $($Args -join ' ') falhou com codigo $LASTEXITCODE"
        }
    }
    finally {
        Set-Location $old
    }
}

function Test-GitApply {
    param(
        [Parameter(Mandatory=$true)][string]$Repo,
        [Parameter(Mandatory=$true)][string]$Patch
    )

    $old = Get-Location
    try {
        Set-Location $Repo
        & git apply --check --whitespace=nowarn $Patch 2>$null
        return ($LASTEXITCODE -eq 0)
    }
    finally {
        Set-Location $old
    }
}

function Apply-Patch {
    param(
        [Parameter(Mandatory=$true)][string]$Repo,
        [Parameter(Mandatory=$true)][string]$Patch,
        [Parameter(Mandatory=$true)][string]$Label
    )

    if (-not (Test-GitApply -Repo $Repo -Patch $Patch)) {
        throw "$Label nao e compativel com o estado atual."
    }

    $old = Get-Location
    try {
        Set-Location $Repo
        & git apply --whitespace=nowarn $Patch
        if ($LASTEXITCODE -ne 0) {
            throw "$Label falhou durante git apply."
        }
    }
    finally {
        Set-Location $old
    }
}

Write-Host ''
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ' Infinity Islands - Instalador Tasks 01 -> 20' -ForegroundColor Cyan
Write-Host ' Preflight transacional + backup + rollback' -ForegroundColor Cyan
Write-Host '============================================================' -ForegroundColor Cyan
Write-Host ''

if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    Fail 'Git nao foi encontrado no PATH.'
}

try {
    $RepoRoot = (& git rev-parse --show-toplevel 2>$null).Trim()
}
catch {
    Fail 'Execute este arquivo dentro da pasta do repositorio Infinity Islands.'
}
if ([string]::IsNullOrWhiteSpace($RepoRoot)) {
    Fail 'Nao foi possivel localizar a raiz do repositorio.'
}

$CurrentBranch = (& git -C $RepoRoot branch --show-current).Trim()
if (-not $AllowOtherBranch -and $CurrentBranch -ne $ExpectedBranch) {
    Fail "Branch atual: '$CurrentBranch'. Esperado: '$ExpectedBranch'. Troque de branch antes de instalar."
}

# Absolutely clean worktree is required so rollback cannot remove user's work.
$Dirty = (& git -C $RepoRoot status --porcelain)
if ($Dirty) {
    Write-Host 'O repositorio possui alteracoes nao commitadas:' -ForegroundColor Yellow
    $Dirty | ForEach-Object { Write-Host ('  ' + $_) -ForegroundColor Yellow }
    Fail 'Faca commit ou stash antes de executar. O instalador nao toca em worktree sujo.'
}

$StartHead = (& git -C $RepoRoot rev-parse HEAD).Trim()
$Timestamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$BackupBranch = "backup/mobile-dungeon-tasks01-20-$Timestamp"

$TempBase = Join-Path ([System.IO.Path]::GetTempPath()) ("InfinityIslandsInstaller-" + [Guid]::NewGuid().ToString('N'))
$PayloadDir = Join-Path $TempBase 'payload'
$TempWorktree = Join-Path $TempBase 'preflight-worktree'
$PayloadZip = Join-Path $TempBase 'payload.zip'

New-Item -ItemType Directory -Path $PayloadDir -Force | Out-Null

