    'dC5wYXRjaFBLAQIUAxQAAAAIAJO0B10OCryl1AAAAKICAAAvAAAAAAAAAAAAAACkgdFtAQBwYXRjaGVzLzIwXzUxX1JVTlRJTUVfV09SS1NQQUNFX0FUVFJT'
    'LmdpdC5wYXRjaFBLAQIUAxQAAAAIAJO0B11Pgd8GsQEAACIEAAA1AAAAAAAAAAAAAACkgfJuAQBwYXRjaGVzLzIwXzUyX1JVTlRJTUVfRklSU1RfUkVXQVJE'
    'X0NPTVBMRVRFLmdpdC5wYXRjaFBLAQIUAxQAAAAIAJO0B10IbOE6qgAAAK8BAAA3AAAAAAAAAAAAAACkgfZwAQBwYXRjaGVzLzIwXzUzX1JVTlRJTUVfR0VO'
    'RVJBVE9SX0NPTlRFTlRfUEhBU0UuZ2l0LnBhdGNoUEsBAhQDFAAAAAgAk7QHXSIw+6rwDgAAKzgAAC4AAAAAAAAAAAAAAKSB9XEBAHBhdGNoZXMvMjBfNjBf'
    'TkVXX0dVSURFRF9JTlRST19GSUxFUy5naXQucGF0Y2hQSwUGAAAAADcANwDvEwAAMYEBAAAA'
    )
    $PayloadB64 = ($PayloadChunks -join '')
    [IO.File]::WriteAllBytes($PayloadZip, [Convert]::FromBase64String($PayloadB64))

    $Hasher = [System.Security.Cryptography.SHA256]::Create()
    try {
        $ActualPayloadSha = ([BitConverter]::ToString(
            $Hasher.ComputeHash([IO.File]::ReadAllBytes($PayloadZip))
        ) -replace '-', '').ToLowerInvariant()
    }
    finally {
        $Hasher.Dispose()
    }

    if ($ActualPayloadSha -ne $PayloadSha256) {
        Fail 'Falha de integridade no payload interno do instalador.'
    }

    Expand-Archive -LiteralPath $PayloadZip -DestinationPath $PayloadDir -Force
    $Manifest = Get-Content (Join-Path $PayloadDir 'manifest.json') -Raw | ConvertFrom-Json

    Write-Host ("Repositorio: " + $RepoRoot)
    Write-Host ("Branch:      " + $CurrentBranch)
    Write-Host ("HEAD:        " + $StartHead)
    Write-Host ("Patches:     " + $Manifest.patch_count)
    Write-Host ''

    # Verify each patch checksum before doing any Git operation.
    foreach ($Entry in $Manifest.patches) {
        $PatchPath = Join-Path $PayloadDir ($Entry.file -replace '/', [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path $PatchPath)) {
            Fail ("Patch ausente no payload: " + $Entry.file)
        }

        $sha = (Get-FileHash -Algorithm SHA256 -LiteralPath $PatchPath).Hash.ToLowerInvariant()
        if ($sha -ne $Entry.sha256) {
            Fail ("Checksum invalido: " + $Entry.file)
        }
    }

    # --------------------------------------------------------
    # Phase 1: PRE-FLIGHT in detached worktree.
    # Real branch remains untouched.
    # --------------------------------------------------------
    Write-Host '[1/4] Criando ambiente temporario de preflight...' -ForegroundColor Cyan
    Run-Git -Args @('worktree', 'add', '--detach', $TempWorktree, $StartHead) -WorkingDirectory $RepoRoot

    Write-Host '[2/4] Testando TODAS as Tasks 01-20 em sequencia...' -ForegroundColor Cyan
    $Index = 0
    foreach ($Entry in $Manifest.patches) {
        $Index++
        $PatchPath = Join-Path $PayloadDir ($Entry.file -replace '/', [IO.Path]::DirectorySeparatorChar)
        $Label = ("Task {0:D2} [{1}/{2}]" -f [int]$Entry.task, $Index, [int]$Manifest.patch_count)

        Write-Host ("  " + $Label) -NoNewline
        try {
            Apply-Patch -Repo $TempWorktree -Patch $PatchPath -Label $Label
            Write-Host '  OK' -ForegroundColor Green
        }
        catch {
            Write-Host '  FALHOU' -ForegroundColor Red
            throw "Preflight interrompido em $Label. O branch REAL nao foi alterado. $($_.Exception.Message)"
        }
    }

    # Verify expected final files in preflight.
    foreach ($Relative in $Manifest.sentinels) {
        $Path = Join-Path $TempWorktree ($Relative -replace '/', [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path $Path)) {
            throw "Preflight terminou, mas arquivo esperado nao existe: $Relative"
        }
    }

    Write-Host ''
    Write-Host '  PRE-FLIGHT COMPLETO: todas as Tasks 01-20 encaixaram.' -ForegroundColor Green
    Write-Host ''

    # --------------------------------------------------------
    # Phase 2: create backup and apply to real branch.
    # --------------------------------------------------------
    Write-Host '[3/4] Criando branch de backup...' -ForegroundColor Cyan
    Run-Git -Args @('branch', $BackupBranch, $StartHead) -WorkingDirectory $RepoRoot
    Write-Host ("  Backup: " + $BackupBranch) -ForegroundColor Green

    Write-Host '[4/4] Aplicando no branch real...' -ForegroundColor Cyan
    $Applied = 0
    try {
        foreach ($Entry in $Manifest.patches) {
            $Applied++
            $PatchPath = Join-Path $PayloadDir ($Entry.file -replace '/', [IO.Path]::DirectorySeparatorChar)
            $Label = ("Task {0:D2} [{1}/{2}]" -f [int]$Entry.task, $Applied, [int]$Manifest.patch_count)

            Write-Host ("  " + $Label) -NoNewline
            Apply-Patch -Repo $RepoRoot -Patch $PatchPath -Label $Label
            Write-Host '  OK' -ForegroundColor Green
        }
    }
    catch {
        Write-Host ''
        Write-Host 'Falha inesperada na aplicacao real. Restaurando HEAD original...' -ForegroundColor Red

        # Worktree was clean at start, so hard reset is safe here.
        Run-Git -Args @('reset', '--hard', $StartHead) -WorkingDirectory $RepoRoot
        Run-Git -Args @('clean', '-fd') -WorkingDirectory $RepoRoot

        throw "Rollback concluido. Nenhuma Task ficou parcialmente instalada. $($_.Exception.Message)"
    }

    # Final sentinels.
    foreach ($Relative in $Manifest.sentinels) {
        $Path = Join-Path $RepoRoot ($Relative -replace '/', [IO.Path]::DirectorySeparatorChar)
        if (-not (Test-Path $Path)) {
            Run-Git -Args @('reset', '--hard', $StartHead) -WorkingDirectory $RepoRoot
            Run-Git -Args @('clean', '-fd') -WorkingDirectory $RepoRoot
            throw "Validacao final falhou em '$Relative'. Rollback executado."
        }
    }

    if ($Commit) {
        Write-Host ''
        Write-Host 'Criando commit unico das Tasks 01-20...' -ForegroundColor Cyan
        Run-Git -Args @('add', '-A') -WorkingDirectory $RepoRoot
        Run-Git -Args @(
            'commit',
            '-m',
            'feat: install mobile dungeon tasks 01-20 and guided intro'
        ) -WorkingDirectory $RepoRoot
    }

    Write-Host ''
    Write-Host '============================================================' -ForegroundColor Green
    Write-Host ' INSTALACAO CONCLUIDA COM SUCESSO' -ForegroundColor Green
    Write-Host '============================================================' -ForegroundColor Green
    Write-Host ''
    Write-Host 'Tasks instaladas: 01 -> 20'
    Write-Host ("Backup de seguranca: " + $BackupBranch)
    if ($Commit) {
        Write-Host 'Alteracoes: commitadas automaticamente.'
    }
    else {
        Write-Host 'Alteracoes: aplicadas, mas NAO commitadas.'
        Write-Host 'Revise com: git status'
        Write-Host 'Depois faca seu commit normalmente.'
    }
    Write-Host ''
}
catch {
    Write-Host ''
    Write-Host ('INSTALADOR INTERROMPIDO: ' + $_.Exception.Message) -ForegroundColor Red
    Write-Host ''
    exit 1
}
finally {
    # Remove detached worktree if it exists.
    if (Test-Path $TempWorktree) {
        try {
            & git -C $RepoRoot worktree remove --force $TempWorktree 2>$null | Out-Null
        }
        catch {}
    }
    try {
        & git -C $RepoRoot worktree prune 2>$null | Out-Null
    }
    catch {}

    if (Test-Path $TempBase) {
        Remove-Item -Recurse -Force $TempBase -ErrorAction SilentlyContinue
    }
}
